'use strict';
const $=id=>document.getElementById(id),C=UAV,M=Missions,KEY='uav-collab-v1',VERSION='2.0.0';
let records=[],session,trial,state,mission=null,draft=null,drag=null,last=performance.now(),lastSave=0;
function config(){try{const c=JSON.parse(localStorage.getItem('uav-research-config-v1')||'{}');return{participant:c.participant||'P001',condition:['action','reason','projection'].includes(c.condition)?c.condition:'action',node:M.categories[c.node]?c.node:'N1',subtype:c.subtype==='dynamic'?'dynamic':'static'}}catch{return{participant:'P001',condition:'action',node:'N1',subtype:'static'}}}
function fresh(){session={id:crypto.randomUUID(),...config()};trial=crypto.randomUUID();mission=null;draft=null;state={status:'ready',route:[[420,500],[420,499]],progress:0,altitude:60,speed:8,battery:82,simTime:0,goalDeferred:false};}
function snap(){return C.clone({state,mission,session})}
function save(){try{localStorage.setItem(KEY,JSON.stringify({version:VERSION,records,session,trial,node:session.node,state,mission}))}catch{toast('记录保存失败，请检查浏览器存储并及时导出')}}
function log(type,label,detail='',before=null){records.push({id:crypto.randomUUID(),version:VERSION,timestamp:new Date().toISOString(),sessionId:session.id,participant:session.participant,condition:session.condition,trialId:trial,node:session.node,obstacleSubtype:mission?.subtype||null,destination:mission?.destination||null,goalDeferred:state.goalDeferred,type,label,detail,reactionMs:['accept','reject','modify_apply'].includes(type)&&state.presentedAt?Date.now()-state.presentedAt:null,before,after:snap(),stimulus:type==='present'?C.clone(mission):undefined});save()}
let toastTimer;function toast(t){$('toast').textContent=t;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').textContent='',4000)}
try{const old=JSON.parse(localStorage.getItem(KEY)||'null');if(old&&Array.isArray(old.records))records=old.records;if(old?.version===VERSION&&old.session&&old.state){session=old.session;trial=old.trial;state=old.state;mission=old.mission;if(state.status==='running')state.status='paused';if(state.status==='editing')state.status='review';log('restore','恢复任务','刷新后保持暂停')}else{fresh();log('session_start','开始会话',old?'升级界面，保留既往记录':'进入飞行界面')}}catch{fresh();toast('旧记录无法读取；本次不会覆盖旧记录，请先联系研究者');throw Error('Stored data unavailable')}
M.destinations.forEach(d=>{const opt=document.createElement('option');opt.value=d.name;$('destinationOptions').append(opt);const b=document.createElement('button');b.textContent='⌖ '+d.name;b.dataset.destination=d.id;b.onclick=()=>{$('destinationInput').value=d.name;document.querySelectorAll('[data-destination]').forEach(e=>e.classList.toggle('selected',e===b));$('destinationMessage').textContent='已选择 '+d.name+'，点击规划路线。';log('destination_select','选择目的地',d.name)};$('destinationList').append(b)});
$('destinationForm').onsubmit=e=>{e.preventDefault();const raw=$('destinationInput').value.trim().replace(/^(请)?(飞往|前往|去)\s*/,''),dest=M.destinations.find(d=>d.name===raw);if(!dest){$('destinationMessage').textContent='请选择列表中的五个预设目的地。';log('destination_invalid','目的地不在预设范围',raw);return}if(!['ready','complete','rejected'].includes(state.status)){toast('请先结束当前任务，再规划新路线');return}const before=snap();session={id:crypto.randomUUID(),...config()};trial=crypto.randomUUID();mission=M.make(session.node,dest.id,session.subtype);state={status:'review',route:C.clone(mission.route),progress:0,altitude:60,speed:8,battery:mission.battery,simTime:0,goalDeferred:false,presentedAt:Date.now()};draft=null;log('present','呈现 AI 建议',mission.name+' / '+dest.name,before);$('destinationMessage').textContent='路线已生成，请复核 AI 建议。';if(innerWidth<760){$('destinationPanel').hidden=true;$('toggleMission').setAttribute('aria-expanded','false')}render();};
function el(tag,text,attrs={}){const e=document.createElement(tag);e.textContent=text;Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));return e}
function renderCards(){const cards=$('satCards');cards.replaceChildren();if(!mission)return;const route=draft?.route||state.route,alt=draft?.altitude||state.altitude,speed=draft?.speed||state.speed,est=C.estimate(route,mission.battery,speed);const target=state.goalDeferred||draft?.goalDeferred?'起降区（原目标暂缓）':mission.destination.name;
const content=[['action','01 现在在做什么',[['目的',`前往${target}`],['过程',`${route.length-1} 个航段 · 高度 ${alt} m · 速度 ${speed} m/s`],['进展',`${Math.round(state.progress*100)}% · ${statusLabel()}`]]],['reason','02 为什么这样做',[['判断依据',mission.reason],['当前方案',draft?'正在修改，应用前检查约束。':state.modified?'操作者已修改路线；上述依据来自原建议。':'采用预设情境规则生成建议。'],['环境与约束',mission.limits]]],['projection','03 接下来会怎样',[['预计结果',`到达 ${target}；全程约 ${est.distance} m / ${est.seconds} 秒；终点电量约 ${est.endBattery}%。`],['潜在局限',mission.limits],['出错可能',mission.error],['既往表现',mission.history]]]];
content.forEach(([key,title,items])=>{const d=document.createElement('details');d.open=true;d.className=session.condition===key?'focus':'';d.append(el('summary',title));items.forEach(([label,text])=>{const p=document.createElement('p');if(label==='进展')p.id='liveProgress';p.append(el('strong',label+' · '),document.createTextNode(text));d.append(p)});d.addEventListener('toggle',()=>{if(d.isConnected&&d.dataset.ready)log('information_toggle','信息展开／收起',`${key}:${d.open}`);d.dataset.ready='1'});cards.append(d)})}
function statusLabel(){return{ready:'待命',review:'等待决策',editing:'修改方案',approved:'方案已确认',running:'飞行中',paused:'悬停 / 已暂停',rejected:'已拒绝 · 悬停',complete:state.goalDeferred?'已返航 · 目标暂缓':'已到达目标'}[state.status]||'待命'}
function render(){document.querySelector('.copilot').scrollTop=0;const editable=state.status==='editing';$('editor').hidden=!editable;$('decisionPanel').hidden=state.status!=='review';$('eventBanner').textContent=mission?mission.event:'等待目的地';$('recTitle').textContent=mission?mission.title:'下一站，由你决定';$('recSummary').textContent=mission?mission.summary:'选择任务点，查看建议航迹。';$('missionHint').textContent=state.goalDeferred?'当前方案：返回起降区，暂缓原目标。':'模拟任务 · 人保留方案选择权';$('play').disabled=!['approved','paused'].includes(state.status);$('play').textContent=state.status==='paused'?'▶ 继续飞行':'▶ 开始飞行';$('pause').disabled=state.status!=='running';renderCards();drawRoute();telemetry()}
function telemetry(){const p=C.sample(state.route,state.progress);if(state.progress>=1&&state.lastHeading!==undefined)p.heading=state.lastHeading;else state.lastHeading=p.heading;const battery=mission?mission.battery-C.length(state.route)*state.progress*.016:82;state.battery=battery;$('battery').textContent=Math.round(battery);$('altitude').textContent=state.altitude;$('speed').textContent=state.status==='running'?state.speed.toFixed(1):'0.0';$('heading').textContent=String(Math.round((p.heading+360)%360)).padStart(3,'0');$('distance').textContent=mission?Math.round(C.length(state.route)*(1-state.progress)):'—';$('elapsed').textContent=String(Math.floor(state.simTime/60)).padStart(2,'0')+':'+String(Math.floor(state.simTime%60)).padStart(2,'0');$('progress').textContent=Math.round(state.progress*100)+'%';$('flightStatus').textContent='● '+statusLabel();if($('liveProgress'))$('liveProgress').textContent='进展 · '+Math.round(state.progress*100)+'% · '+statusLabel();if($('traffic'))$('traffic').setAttribute('transform',`translate(${Math.sin(state.simTime*.4)*25} 0)`);$('drone').setAttribute('transform',`translate(${p.x} ${p.y}) rotate(${p.heading})`);window.flightView?.update({...p,altitude:state.altitude});}
const svgNS='http://www.w3.org/2000/svg';function svg(tag,attrs){const e=document.createElementNS(svgNS,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));return e}
function drawRoute(){const route=draft?.route||state.route;$('originalRoute').setAttribute('points',mission?.initialRoute.map(p=>p.join(',')).join(' ')||'');$('activeRoute').setAttribute('points',mission?state.route.map(p=>p.join(',')).join(' '):'');$('suggestedRoute').setAttribute('points',['review','editing'].includes(state.status)?route.map(p=>p.join(',')).join(' '):'');$('waypoints').replaceChildren();$('hazards').replaceChildren();if(!mission)return;
if(mission.hazard){const h=mission.hazard;$('hazards').append(svg('circle',{cx:h.x,cy:h.y,r:h.r+h.margin,fill:'#ff635333',stroke:'#ff9e67','stroke-width':3,'stroke-dasharray':'8 6'}));if(mission.subtype==='dynamic'){$('hazards').append(svg('path',{id:'traffic',d:`M${h.x-12} ${h.y-9} L${h.x+13} ${h.y} L${h.x-12} ${h.y+9}Z`,fill:'#ff654b',stroke:'white','stroke-width':2}));}}
route.forEach((p,i)=>{const g=svg('g',{transform:`translate(${p[0]} ${p[1]})`,class:'waypoint',tabindex:0,role:'button','aria-label':i===route.length-1?'目的地':`航点 ${i}`});g.append(svg('circle',{r:11,fill:i===route.length-1?'#b5f67b':'#172f29',stroke:'#ffe1a0','stroke-width':3}));const t=svg('text',{x:15,y:5,fill:'white','font-size':17,'paint-order':'stroke',stroke:'#14251f','stroke-width':3});t.textContent=i===0?'S':i===route.length-1?'目标':i;g.append(t);if(draft&&i>0&&i<route.length-1){g.onpointerdown=e=>{e.preventDefault();e.stopPropagation();drag={index:i,before:snap()};missionMap.dragging.disable();g.setPointerCapture(e.pointerId)};g.onpointermove=e=>{if(drag?.index!==i)return;const pt=$('map').createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const q=pt.matrixTransform($('map').getScreenCTM().inverse());draft.route[i]=[Math.max(35,Math.min(865,q.x)),Math.max(35,Math.min(625,q.y))];g.setAttribute('transform',`translate(${draft.route[i]})`);$('suggestedRoute').setAttribute('points',draft.route.map(p=>p.join(',')).join(' '))};const end=()=>{if(!drag)return;log('waypoint_edit','修改航点',JSON.stringify(draft.route[i]),drag.before);drag=null;missionMap.dragging.enable();validateDraft();renderCards()};g.onpointerup=end;g.onpointercancel=end;g.onkeydown=e=>{const moves={ArrowUp:[0,-5],ArrowDown:[0,5],ArrowLeft:[-5,0],ArrowRight:[5,0]};if(moves[e.key]){e.preventDefault();draft.route[i]=draft.route[i].map((v,j)=>v+moves[e.key][j]);log('waypoint_edit','键盘修改航点',String(i));drawRoute();validateDraft()}}}else g.onclick=()=>toast(i===route.length-1?(state.goalDeferred||draft?.goalDeferred?'起降区':mission.destination.name):`航点 ${i} · ${p.map(Math.round).join(', ')}`);$('waypoints').append(g)});}
function decide(type){if(state.status!=='review')return;const before=snap();state.status=type==='accept'?'approved':'rejected';log(type,type==='accept'?'接受方案':'拒绝方案',mission.title,before);render()}
$('accept').onclick=()=>decide('accept');$('reject').onclick=()=>decide('reject');
$('modify').onclick=()=>{const before=snap();state.status='editing';draft={route:C.clone(state.route),altitude:state.altitude,speed:state.speed,goalDeferred:false};$('strategy').value='recommended';$('editAlt').value=state.altitude;$('editSpeed').value=state.speed;$('rationale').value='';log('modify_start','开始修改','',before);render();validateDraft()};
function validateDraft(){if(!draft)return;draft.altitude=Number($('editAlt').value);draft.speed=Number($('editSpeed').value);const errors=C.validate(draft.route,mission,draft.altitude,draft.speed);$('validation').textContent=errors.length?errors.join('；'):(draft.goalDeferred?'检查通过；将暂缓原目标，返回起降区。':'二维几何与模拟电量检查通过。');$('applyEdit').disabled=errors.length>0;return errors}
$('strategy').onchange=()=>{draft.route=C.clone($('strategy').value==='alternative'?mission.alternative:mission.route);draft.goalDeferred=mission.id==='N5'&&$('strategy').value==='alternative'&&mission.destination.id!=='home';log('strategy_change','切换方案',$('strategy').value);drawRoute();validateDraft();renderCards()};for(const id of ['editAlt','editSpeed'])$(id).oninput=()=>{validateDraft();renderCards()};
$('applyEdit').onclick=()=>{if(!draft||validateDraft().length)return;const before=snap();Object.assign(state,draft,{status:'approved',modified:true});const detail=JSON.stringify({route:draft.route,altitude:draft.altitude,speed:draft.speed,rationale:$('rationale').value});draft=null;log('modify_apply','应用修改',detail,before);render()};$('cancelEdit').onclick=()=>{draft=null;state.status='review';log('modify_cancel','取消修改');render()};
$('play').onclick=()=>{if(!['approved','paused'].includes(state.status))return;const before=snap();state.status='running';log('play','开始／继续飞行','实时 1× 仿真',before);$('destinationPanel').hidden=true;$('toggleMission').setAttribute('aria-expanded','false');render()};$('pause').onclick=()=>{if(state.status!=='running')return;const before=snap();state.status='paused';log('pause','暂停飞行','',before);render()};
$('reset').onclick=()=>{if(mission&&!['complete','rejected','ready'].includes(state.status)&&!confirm('结束当前模拟任务并重新选择目的地？已有操作记录会保留。'))return;log('mission_end','结束当前任务');fresh();log('session_start','开始新任务');$('destinationPanel').hidden=false;$('toggleMission').setAttribute('aria-expanded','true');render()};
$('toggleMission').onclick=()=>{$('destinationPanel').hidden=!$('destinationPanel').hidden;$('toggleMission').setAttribute('aria-expanded',String(!$('destinationPanel').hidden));log('panel_toggle','目的地面板',String(!$('destinationPanel').hidden))};$('toggleAI').onclick=()=>{$('aiBody').hidden=!$('aiBody').hidden;$('toggleAI').textContent=$('aiBody').hidden?'+':'−';$('toggleAI').setAttribute('aria-expanded',String(!$('aiBody').hidden));log('panel_toggle','AI 面板',String(!$('aiBody').hidden))};$('expandMap').onclick=()=>{document.body.classList.toggle('map-expanded');$('expandMap').textContent=document.body.classList.contains('map-expanded')?'缩小 ↙':'展开 ↗';log('map_expand','地图视图切换',String(document.body.classList.contains('map-expanded')))};
$('pitch').oninput=()=>{window.flightView?.pitch($('pitch').value);$('pitchValue').textContent='−'+$('pitch').value+'°'};$('pitch').onchange=()=>log('camera_pitch','调整云台',$('pitch').value);$('capture').onclick=()=>{try{if(!window.flightView)throw Error();const a=document.createElement('a');a.href=flightView.capture();a.download='uav-simulated-view.png';a.click();log('capture','保存模拟视角')}catch{toast('当前设备无法保存视角')}};
window.addEventListener('uav-map-action',e=>log(e.detail.type,'地图操作',e.detail.text));document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.status==='running'){state.status='paused';render()}log('visibility','页面可见性变化',document.visibilityState)});window.addEventListener('pagehide',save);
function tick(now){const dt=Math.min((now-last)/1000,.25);last=now;if(state.status==='running'){state.simTime+=dt;state.progress=Math.min(1,state.progress+dt*state.speed/C.length(state.route));telemetry();if(state.progress>=1){state.status='complete';log('complete','任务结束',state.goalDeferred?'已返航，原目标暂缓':'到达 '+mission.destination.name);render()}else if(now-lastSave>2000){save();lastSave=now}}requestAnimationFrame(tick)}if(mission){$('destinationInput').value=mission.destination.name;$('destinationPanel').hidden=true;$('toggleMission').setAttribute('aria-expanded','false')}render();requestAnimationFrame(tick);
